def header(back, title, listen=True):
    l = f'<button type="button" style="display: inline-flex; align-items: center; gap: 6px; height: 44px; padding: 0 14px; border: 0; border-radius: 22px; background: #FFFFFF; color: {PRI}; font-family: inherit; font-size: 14px; font-weight: 700; cursor: pointer">{svg("sound", 20)}Listen</button>' if listen else ''
    return f'<div style="display: flex; align-items: center; gap: 10px"><a href="{back}" aria-label="Back" style="flex: none; display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: 22px; background: #FFFFFF; color: {INK}">{svg("left")}</a><span style="flex-grow: 1; font-size: 15px; font-weight: 700">{title}</span>{l}</div>'
def navbar(active, T=EN):
    def it(icon, t, key, href):
        on = key == active
        st = f'background: {TINT}; color: {PRI}; border-radius: 26px;' if on else f'color: {MUT};'
        return f'<a href="{href}"{" aria-current=page" if False else ""} style="display: flex; align-items: center; justify-content: center; gap: 8px; height: 52px; {st} text-decoration: none; font-size: 14px; font-weight: 700">{svg(icon, 22)}{t}</a>'
    return f'<nav aria-label="Main" style="display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); padding: 8px; border-radius: 36px; background: #FFFFFF">{it("home", T["home"], "home", "Home.dc.html")}{it("game", T["gnav"], "game", "Game.dc.html")}{it("report", T["rep"], "rep", "Children.dc.html")}</nav>'
