ASKMIC = lambda: f'<a href="VoiceMenu.dc.html" aria-label="Ask Khoj" style="flex: none; display: flex; align-items: center; justify-content: center; width: 52px; height: 52px; border-radius: 26px; background: {PRI}; color: #FFFFFF; box-shadow: 0 8px 16px rgba(156,69,96,0.28)">{svg("mic", 24)}</a>'
def screen(row, fname, title, parts, footer='', h=917, gap=14, bg=BG, lang='en', rtl=False, font=EN_F, ask='mic', css='', prefoot='', logic=None):
    if ask == 'bar': foot = f'<div style="margin-top: auto; display: flex; flex-direction: column; gap: 10px">{prefoot}{ASKFULL()}{footer}</div>'
    elif ask == 'mic': foot = f'<div style="margin-top: auto; display: flex; align-items: flex-end; gap: 10px"><div style="flex-grow: 1; min-width: 0; display: flex; flex-direction: column; gap: 10px">{footer}</div>{ASKMIC()}</div>'
    else: foot = f'<div style="margin-top: auto; display: flex; flex-direction: column; gap: 10px">{footer}</div>' if footer else ''
    d = ' dir="rtl" lang="ur"' if rtl else ''
    body = f'<div{d} style="position: relative; width: 412px; height: {h}px; box-sizing: border-box; padding: 24px 20px 16px; display: flex; flex-direction: column; gap: {gap}px; background: {bg}; color: {INK}; font-family: {font}">{"".join(parts)}{foot}</div>'
    BODIES[fname] = body
    page(fname, title, F, PRI, INK, body, h=h, lang=lang, css=css, logic=logic); reg(row, fname, title, h, inter=bool(logic))
BODIES = {}
BEHIND = {'Home': 'Home.dc.html', 'History-taking with parents': 'Step2.dc.html', 'Clinical and behavioural interview': 'Step3.dc.html', 'Treatment planning': 'Step7.dc.html', 'DSM-5 criteria for ADHD': 'Signs.dc.html'}
def sheet(row, fname, title, behind, inner, footer=''):
    body = (f'<div style="position: relative; overflow: hidden; width: 412px; height: 917px; color: {INK}; font-family: {EN_F}">'
      f'<div aria-hidden="true" inert style="position: absolute; left: 0; top: 0; filter: blur(5px); pointer-events: none">{BODIES[behind if behind.endswith('.dc.html') else BEHIND[behind]]}</div>'
      f'<div aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 412px; height: 917px; background: rgba(94,38,58,0.48); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px)"></div>'
      f'<div style="position: absolute; left: 0; bottom: 0; width: 412px; box-sizing: border-box; display: flex; flex-direction: column; gap: 14px; padding: 12px 20px 20px; border-radius: 28px 28px 0 0; background: {BG}; box-shadow: 0 -12px 40px rgba(60,16,34,0.25)"><span style="align-self: center; width: 44px; height: 5px; border-radius: 3px; background: {LINE}"></span>{inner}{footer}</div></div>')
    page(fname, title, F, PRI, INK, body); reg(row, fname, title)
def popcard(row, fname, title, behind, icon, heading, sublabel, items, footer=''):
    rows = ''.join(f'<li style="display: flex; align-items: flex-start; gap: 12px; padding: 12px 0; {"border-top: 1px solid " + LINE + ";" if i else ""}"><span style="flex: none; display: flex; align-items: center; justify-content: center; width: 26px; height: 26px; border-radius: 13px; background: {TINT}; color: {PRI}; font-size: 12px; font-weight: 800">{i + 1}</span><span style="font-size: 15px; line-height: 22px; padding-top: 2px">{t}</span></li>' for i, t in enumerate(items))
    body = (f'<div style="position: relative; overflow: hidden; width: 412px; height: 917px; color: {INK}; font-family: {EN_F}">'
      f'<div aria-hidden="true" inert style="position: absolute; left: 0; top: 0; filter: blur(5px); pointer-events: none">{BODIES[behind]}</div>'
      f'<div aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 412px; height: 917px; background: rgba(94,38,58,0.48); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px)"></div>'
      f'<div style="position: absolute; left: 0; top: 0; width: 412px; height: 917px; box-sizing: border-box; padding: 0 20px; display: flex; flex-direction: column; justify-content: center"><div style="display: flex; flex-direction: column; gap: 6px; padding: 14px 16px 16px; border-radius: 22px; background: #FFFFFF; box-shadow: 0 5px 0 #E3B9C6, 0 24px 50px rgba(60,16,34,0.35)">'
      f'<div style="display: flex; align-items: center; gap: 12px">{ic(icon, 42)}<span style="flex-grow: 1; font-size: 15px; line-height: 20px; font-weight: 700">{heading}</span><a href="{behind}" aria-label="Close" style="flex: none; display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: 22px; background: {TINT}; color: {INK}">{svg("close", 20)}</a></div>'
      f'<span style="font-size: 13px; font-weight: 600; color: {MUT}">{sublabel}</span><ol style="margin: 0; padding: 0; list-style: none">{rows}</ol>{footer}</div></div></div>')
    page(fname, title, F, PRI, INK, body); reg(row, fname, title)
def popfoot(label, nxt, href='#'): return f'<div style="display: flex; align-items: center; gap: 12px; margin-top: 6px"><span style="flex-grow: 1; font-size: 13px; font-weight: 700; color: {MUT}">{label}</span>{btn(nxt, href, "pri", None, 46)}</div>'
def gotit(href): return f'<div style="margin-top: 6px">{btn("Got it", href, "pri", None, 46)}</div>'
def more(t, d, href): return f'<a href="{href}" style="display: flex; align-items: center; gap: 12px; padding: 14px 16px; border-radius: 22px; background: #FFFFFF; color: {INK}; text-decoration: none; box-shadow: 0 5px 0 #E3B9C6, 0 12px 20px rgba(156,69,96,0.14); margin-bottom: 5px"><span style="flex-grow: 1; display: flex; flex-direction: column; gap: 2px"><span style="font-size: 15px; line-height: 21px; font-weight: 700">{t}</span><span style="font-size: 14px; line-height: 20px; color: {MUT}">{d}</span></span><span style="flex: none; display: flex; align-items: center; justify-content: center; width: 36px; height: 36px; border-radius: 18px; background: {TINT}; color: {PRI}">{svg('right', 20, 2.5)}</span></a>'
def stepper(cur):
    s = ''
    for i in range(1, 8):
        if i < cur: c = f'<span style="flex: none; display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 14px; background: {TINT}; color: {PRI}">{svg("check", 16, 2.5)}</span>'
        elif i == cur: c = f'<span style="flex: none; display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 14px; background: {PRI}; color: #FFFFFF; font-size: 13px; font-weight: 700">{i}</span>'
        else: c = f'<span style="flex: none; display: flex; align-items: center; justify-content: center; width: 26px; height: 26px; border-radius: 14px; border: 1px solid {MUT}; color: {MUT}; font-size: 12px; font-weight: 600">{i}</span>'
        s += c + (f'<span style="flex-grow: 1; height: 2px; background: {PRI if i < cur else LINE}"></span>' if i < 7 else '')
    return f'<div style="display: flex; align-items: center">{s}</div>'
def prevnext(prev, nxt, nl='Next step'):
    return grid(btn('Previous', prev, 'out') + btn(nl, nxt), 2, 12)
def step(fname, n, title, text, content, prev, nxt, chips='', nl='Next step'):
    screen(2, fname, f'Step {n} · {title}', [header('Path.dc.html', 'The diagnostic path'), stepper(n), col(eyebrow(f'STEP {n} OF 7') + h1(title, 22) + lead(text) + (rowf(chips, 8, 'flex-wrap: wrap') if chips else ''), 8), content], prevnext(prev, nxt, nl))
def field(label, typ, val='', ph=''):
    i = 'f-' + label.lower().replace(' ', '-')
    return f'<div style="display: flex; flex-direction: column; gap: 6px"><label for="{i}" style="font-size: 13px; font-weight: 700">{label}</label><input id="{i}" type="{typ}" value="{val}" placeholder="{ph}" style="height: 52px; box-sizing: border-box; padding: 0 18px; border: 2px solid {LINE}; border-radius: 26px; background: #FFFFFF; color: {INK}; font-family: inherit; font-size: 16px"></div>'
def seg(items, on, hrefs=None):
    s = ''
    for i, t in enumerate(items):
        st = f'background: {PRI}; color: #FFFFFF;' if i == on else f'color: {MUT};'
        s += f'<a href="{hrefs[i] if hrefs else "#"}" style="display: flex; align-items: center; justify-content: center; min-height: 46px; padding: 0 6px; border-radius: 18px; {st} text-decoration: none; font-size: 13px; line-height: 16px; font-weight: 700; text-align: center">{t}</a>'
    return f'<div style="display: grid; grid-template-columns: repeat({len(items)}, minmax(0, 1fr)); gap: 4px; padding: 6px; border-radius: 24px; background: #FFFFFF">{s}</div>'
def note(t, bg=SKY): return f'<p style="margin: 0; padding: 14px 16px; border-radius: 20px; background: {bg}; font-size: 14px; line-height: 20px; font-weight: 600">{t}</p>'
def sub(t): return f'<h2 style="margin: 0; font-size: 13px; font-weight: 600; color: {MUT}">{t}</h2>'
SAFE = lead('Khoj explains and guides. Only a clinician can diagnose.', 12)


GLASS = 'background: rgba(255,255,255,0.55); -webkit-backdrop-filter: blur(18px); backdrop-filter: blur(18px); border: 1px solid rgba(255,255,255,0.9); box-shadow: 0 20px 40px rgba(156,69,96,0.12)'
SER = "Fraunces, Georgia, serif"
def blob(st, c, b=46): return f'<span style="position: absolute; {st}; border-radius: 50%; background: {c}; filter: blur({b}px)"></span>'
def gscreen(row, fname, title, decor, inner, pad='24px 20px 16px', css='', bg=BG, fg=INK, logic=None):
    body = f'<div style="position: relative; overflow: hidden; width: 412px; height: 917px; box-sizing: border-box; padding: {pad}; background: {bg}; color: {fg}; font-family: {EN_F}"><div aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 412px; height: 917px; overflow: hidden">{decor}</div><div style="position: relative; display: flex; flex-direction: column; gap: 14px; height: 100%">{inner}</div></div>'
    page(fname, title, F, PRI, INK, body, css=css, logic=logic); reg(row, fname, title, inter=bool(logic))
def gfield(label, typ, val=''):
    i = 'g-' + label.lower().replace(' ', '-')
    return f'<div style="display: flex; flex-direction: column; gap: 6px"><label for="{i}" style="font-size: 13px; font-weight: 700">{label}</label><input id="{i}" type="{typ}" value="{val}" style="height: 52px; box-sizing: border-box; padding: 0 18px; border: 1px solid rgba(255,255,255,0.95); border-radius: 26px; background: rgba(255,255,255,0.72); color: {INK}; font-family: inherit; font-size: 16px"></div>'
ORDIV = f'<div style="display: flex; align-items: center; gap: 10px; font-size: 13px; color: {MUT}"><span style="flex-grow: 1; height: 1px; background: {LINE}"></span>Or<span style="flex-grow: 1; height: 1px; background: {LINE}"></span></div>'
BLOBS = blob('left: -70px; top: 60px; width: 280px; height: 280px', '#EDB9C9') + blob('right: -70px; top: 250px; width: 260px; height: 260px', '#B3D0EE') + blob('left: 120px; top: 20px; width: 120px; height: 120px', '#F6DFE5', 20)


# ---- characters and small illustrations
SKIN = '#E9BFA6'; HAIR = '#3A2630'
def person(kind, x, y, sc=1.0):
    top = {'parent': PRI, 'child': '#6E93BF', 'clinician': '#FFFFFF', 'teacher': SKYINK}[kind]
    g = f'<g transform="translate({x} {y}) scale({sc})">'
    if kind == 'parent': g += f'<circle cx="0" cy="-1" r="21" fill="{PRI}"></circle>'
    g += f'<rect x="-26" y="20" width="52" height="64" rx="22" fill="{top}"' + (f' stroke="{LINE}" stroke-width="2"' if kind == 'clinician' else '') + '></rect>'
    if kind == 'parent': g += '<path d="M-21,4 Q-30,40 -22,60 L-8,30 Z" fill="#B5607A"></path>'
    g += f'<rect x="-5" y="12" width="10" height="12" fill="{SKIN}"></rect><circle cx="0" cy="0" r="16" fill="{SKIN}"></circle>'
    if kind == 'parent': g += f'<path d="M-16.5,-2 A16.5,16.5 0 0 1 16.5,-2 Q0,-12 -16.5,-2 Z" fill="{PRI}"></path>'
    elif kind == 'teacher': g += f'<path d="M-16,0 A16,16 0 0 1 16,0 Q8,-8 0,-8 Q-8,-8 -16,0 Z" fill="{HAIR}"></path><circle cx="0" cy="-17" r="6" fill="{HAIR}"></circle>'
    else: g += f'<path d="M-16,-1 A16,16 0 0 1 16,-1 Q0,-9 -16,-1 Z" fill="{HAIR}"></path>'
