 '@keyframes leafdrop{0%{opacity:0;transform:translateY(-170px) rotate(-50deg)}40%{opacity:1;transform:translateY(0) rotate(0)}75%{opacity:1;transform:translateY(0) rotate(0)}100%{opacity:0;transform:translateY(26px) rotate(12deg)}}'
