def counter(k, final=False):
    num = f'<span style="font-family: {SER}; font-size: 20px; line-height: 24px; font-weight: 500">{k}</span>'
    if k and not final: num = f'<span style="display: block; height: 24px; overflow: hidden"><span style="display: flex; flex-direction: column; transform: translateY(-24px); animation: roll .6s cubic-bezier(.2,.8,.2,1) .35s both"><span style="font-family: {SER}; font-size: 20px; line-height: 24px; font-weight: 500">{k - 1}</span><span style="font-family: {SER}; font-size: 20px; line-height: 24px; font-weight: 500">{k}</span></span></span>'
    an = 'animation: badgein .5s ease 3.3s both' if final else ('animation: pop .5s ease .6s both' if k else '')
    return f'<span class="cnt" aria-label="{k} of the game’s parts so far" style="flex: none; margin-left: auto; display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 12px 0 10px; border-radius: 18px; background: {TINT}; color: {PRI}; {an}">{svg("leaf", 18)}{num}</span>'
