def gprog(a, b):
    if a is None: return col(f'<div style="display: flex; gap: 3px; height: 10px"><span style="flex-grow: 19; border-radius: 5px; background: #E3B9C6"></span><span style="flex-grow: 6; border-radius: 5px; background: {PRI}"></span></div>' + f'<span style="font-size: 12px; font-weight: 600; color: {MUT}">The tablet game is done. This phase is one week at home.</span>', 6)
    seg = lambda g, c: f'<span style="flex-grow: {g}; flex-basis: 0; background: {c}"></span>' if g > 0 else ''
    return col(f'<div style="display: flex; height: 10px; border-radius: 5px; overflow: hidden; background: #FFFFFF">{seg(a, "#E3B9C6")}{seg(b - a, PRI)}{seg(19 - b, "#FFFFFF")}</div>', 6)
def ppath(parts, psel, pfiles):
    out = ''
    for i, p in enumerate(parts):
        st = (f'background: {TINT}; color: {PRI}; box-shadow: 0 4px 0 #E3B9C6' if i < psel else f'background: {PRI}; color: #FFFFFF; box-shadow: 0 4px 0 #7A3049' if i == psel else f'background: #FFFFFF; color: {MUT}; box-shadow: 0 4px 0 #E3B9C6')
        out += f'<a href="{pfiles[i]}" aria-label="Part {p[0]}" style="flex: none; display: flex; align-items: center; justify-content: center; width: 42px; height: 42px; border-radius: 21px; {st}; text-decoration: none; font-size: 15px; font-weight: 800">{svg("check", 18, 2.5) if i < psel else p[0]}</a>'
        if i < len(parts) - 1: out += f'<span style="flex-grow: 1; height: 4px; background: {PRI if i < psel else RC}"></span>'
    return f'<div style="display: flex; align-items: center; padding-bottom: 4px">{out}</div>'
