CNT = [0]
def phase(n, does, meas, sel, parts=None, psel=0, insp=None, attn=None, pfiles=None, anim='', span=(None, None)):
    name, dur, _, fn = PH[n - 1]
    CNT[0] += 1; k = CNT[0]
    if pfiles: fn = pfiles[psel]
    top = [header('GameFlow.dc.html', f'Phase {n} of 5'), col(rowf(chip(dur) + (chip('Inspired by ' + insp[0], 'white', insp[1]) if insp else '') + counter(k, k == 10), 8) + h1(name, 22), 6), gprog(*span)]
    nxt = PH[n][3] if n < 5 else 'Game.dc.html'; prv = PH[n - 2][3] if n > 1 else 'GameFlow.dc.html'; nl = 'Next phase' if n < 5 else 'Finish'
    if parts:
        top.append(col(sub(f'{len(parts)} parts, one after another') + ppath(parts, psel, pfiles) + card(rowf(f'<span style="flex-grow: 1; font-size: 16px; font-weight: 800">Part {parts[psel][0]}</span>' + chip(parts[psel][1], 'white'), 8) + anim + ''.join(f'<p style="margin: 0; font-size: 14px; line-height: 20px">{t}</p>' for t in parts[psel][2]), TINT, '14px', 8), 8))
        if psel < len(parts) - 1: nxt, nl = pfiles[psel + 1], 'Next part'
        if psel > 0: prv = pfiles[psel - 1]
    else:
        top.append(card(sub('What your child does') + anim + ''.join(f'<p style="margin: 0; font-size: 15px; line-height: 21px; font-weight: 600">{d}</p>' for d in does), TINT, '14px', 8))
    defs = dict(MEAS)
    if attn: defs['Attention'] = attn
    where = f'in Part {parts[psel][0]}' if parts else 'in this phase'
    if n == 5:
        top.append(f'<button type="button" onClick="{{{{ togglePdf }}}}" style="display: flex; align-items: center; justify-content: center; gap: 8px; height: 50px; border: 2px solid {PRI}; border-radius: 25px; background: transparent; color: {PRI}; font-family: inherit; font-size: 15px; font-weight: 700; cursor: pointer">{svg("report", 20)}View the tracker PDF</button>')
        top.append(f'<sc-if value="{{{{ pdf }}}}" hint-placeholder-val="{{{{ false }}}}"><div style="position: absolute; z-index: 2; left: 0; top: 0; width: 412px; height: 917px; box-sizing: border-box; padding: 0 20px; display: flex; flex-direction: column; justify-content: center; background: rgba(94,38,58,0.48); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px)"><div style="display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 24px 20px 18px; border-radius: 22px; background: #FFFFFF; text-align: center; box-shadow: 0 5px 0 #E3B9C6, 0 24px 50px rgba(60,16,34,0.35)">{ic("clock", 56)}<span style="font-size: 18px; line-height: 24px; font-weight: 800">Not released yet</span><span style="font-size: 15px; line-height: 22px; color: {MUT}">The homework tracker PDF is still being prepared. It will appear here once it is released.</span><button type="button" onClick="{{{{ togglePdf }}}}" style="align-self: stretch; height: 46px; margin-top: 6px; border: 0; border-radius: 23px; background: {PRI}; color: #FFFFFF; font-family: inherit; font-size: 15px; font-weight: 700; cursor: pointer">Got it</button></div></div></sc-if>')
    if k == 10: top.append(FINALE)
    n_m = f'{len(meas)} things' if len(meas) > 1 else '1 thing'
    top.append(f'<button type="button" onClick="{{{{ toggle }}}}" style="display: flex; align-items: center; gap: 12px; padding: 12px 16px; border: 0; border-radius: 22px; background: #FFFFFF; color: {INK}; font-family: inherit; text-align: left; cursor: pointer; box-shadow: 0 5px 0 #E3B9C6, 0 12px 20px rgba(156,69,96,0.14); margin-bottom: 5px">{ic("eye", 42)}<span style="flex-grow: 1; display: flex; flex-direction: column; gap: 2px"><span style="font-size: 15px; line-height: 21px; font-weight: 700">What’s measured</span><span style="font-size: 13px; line-height: 18px; color: {MUT}">{n_m} {where}. Tap to see.</span></span><span style="flex: none; display: flex; align-items: center; justify-content: center; width: 36px; height: 36px; border-radius: 18px; background: {TINT}; color: {PRI}">{svg("right", 20, 2.5)}</span></button>')
    rows = ''.join(f'<li style="display: flex; flex-direction: column; gap: 1px; padding: 9px 0; {"border-top: 1px solid " + LINE + ";" if i else ""}"><span style="font-size: 14px; line-height: 20px; font-weight: 800">{m}</span><span style="font-size: 13px; line-height: 19px; color: {MUT}">{defs[m]}</span></li>' for i, m in enumerate(meas))
    top.append(f'<sc-if value="{{{{ open }}}}" hint-placeholder-val="{{{{ false }}}}"><div style="position: absolute; left: 0; top: 0; width: 412px; height: 917px; box-sizing: border-box; padding: 0 20px; display: flex; flex-direction: column; justify-content: center; background: rgba(94,38,58,0.48); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px)"><div style="display: flex; flex-direction: column; gap: 4px; padding: 14px 16px 16px; border-radius: 22px; background: #FFFFFF; box-shadow: 0 5px 0 #E3B9C6, 0 24px 50px rgba(60,16,34,0.35)"><div style="display: flex; align-items: center; gap: 12px">{ic("eye", 42)}<span style="flex-grow: 1; font-size: 15px; line-height: 20px; font-weight: 700">What’s measured {where}</span><button type="button" onClick="{{{{ toggle }}}}" aria-label="Close" style="flex: none; display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; border: 0; border-radius: 22px; background: {TINT}; color: {INK}; cursor: pointer">{svg("close", 20)}</button></div><ul style="margin: 0; padding: 0; list-style: none">{rows}</ul></div></div></sc-if>')
    screen(5, fn, f'Phase {n} · {name}' + (f' · Part {parts[psel][0]}' if parts and psel else ''), top, prevnext(prv, nxt, nl), css=ANIM, gap=12, logic=MLOGIC)
