def leaf(i, t, href, state, w=104, h=92, top=None, icon=None, x=None):
    st = (f'background: {PRI}; color: #FFFFFF; box-shadow: 0 5px 0 #7A3049' if state == 'on' else f'background: {TINT}; color: {PRI}; box-shadow: 0 5px 0 #E3B9C6' if state == 'done' else f'background: #FFFFFF; color: {INK}; box-shadow: 0 5px 0 #E3B9C6')
    pos = f'position: absolute; left: {x}px; top: {top}px; ' if x is not None else ''
    head = svg(icon, 22) if icon else (svg('check', 20, 2.5) if state == 'done' else f'<span style="font-family: {SER}; font-size: 22px; line-height: 24px; font-weight: 500">{i + 1}</span>')
    return f'<a href="{href}" style="{pos}display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; width: {w}px; height: {h}px; box-sizing: border-box; padding: 6px 12px; border-radius: {LA if i % 2 == 0 else LB}; {st}; text-decoration: none; font-size: 13px; line-height: 17px; font-weight: 700; text-align: center">{head}{t}</a>'
